import path from 'path';
import { and, eq, isNull } from 'drizzle-orm';
import { openDurableDatabase, transaction, closeDatabase } from './database';
import { COORDINATOR_SCHEMA } from './migrations';
import { coordinator } from './schema/coordinator';

type Database = Awaited<ReturnType<typeof openDurableDatabase>>;
type CoordinatorRecord = Pick<
  typeof coordinator.$inferSelect,
  'pid' | 'token' | 'port'
>;
const COORDINATOR_SINGLETON = 1;

export class CoordinatorRecords {
  private constructor(private readonly db: Database) {}

  static async open(root: string): Promise<CoordinatorRecords> {
    return new CoordinatorRecords(
      await openDurableDatabase({
        databasePath: path.join(root, 'runtime', 'coordinator.sqlite'),
        schema: COORDINATOR_SCHEMA,
      }),
    );
  }

  transaction<T>(operation: () => T): T {
    return transaction(this.db, operation);
  }

  read(): CoordinatorRecord | null {
    return (
      this.db
        .select({
          pid: coordinator.pid,
          token: coordinator.token,
          port: coordinator.port,
        })
        .from(coordinator)
        .where(eq(coordinator.singleton, COORDINATOR_SINGLETON))
        .get() ?? null
    );
  }

  assign(record: CoordinatorRecord): void {
    this.db
      .insert(coordinator)
      .values({ singleton: COORDINATOR_SINGLETON, ...record })
      .onConflictDoUpdate({ target: coordinator.singleton, set: record })
      .run();
  }

  publish({ pid, token, port }: CoordinatorRecord): boolean {
    return this.transaction(() => {
      return (
        this.db
          .update(coordinator)
          .set({ port })
          .where(
            and(
              eq(coordinator.singleton, COORDINATOR_SINGLETON),
              eq(coordinator.pid, pid),
              eq(coordinator.token, token),
            ),
          )
          .run().changes === 1
      );
    });
  }

  release({ pid, token }: Omit<CoordinatorRecord, 'port'>): void {
    this.transaction(() => {
      this.db
        .delete(coordinator)
        .where(and(eq(coordinator.pid, pid), eq(coordinator.token, token)))
        .run();
    });
  }

  discard({ pid, token, port }: CoordinatorRecord): boolean {
    return (
      this.db
        .delete(coordinator)
        .where(
          and(
            eq(coordinator.singleton, COORDINATOR_SINGLETON),
            eq(coordinator.pid, pid),
            eq(coordinator.token, token),
            port === null
              ? isNull(coordinator.port)
              : eq(coordinator.port, port),
          ),
        )
        .run().changes === 1
    );
  }

  close(): void {
    closeDatabase(this.db);
  }
}
